def run(inputs: dict) -> dict:
    import numpy as np

    metrics = inputs.get("ExtractedMetric", [])
    if not metrics:
        raise ValueError("Нет данных ExtractedMetric")

    values = []
    units = set()
    for m in metrics:
        sf = m.get("scalar_fact")
        if sf is None:
            continue
        v = sf.get("value")
        u = sf.get("unit")
        if v is None or u is None:
            continue
        values.append(v)
        units.add(u)

    if len(values) < 2:
        raise ValueError("Недостаточно значений для расчёта коэффициента вариации (нужно минимум 2)")

    if len(units) > 1:
        raise ValueError(f"Обнаружены разные единицы измерения: {units}")

    arr = np.array(values, dtype=float)
    mean = np.mean(arr)
    if mean == 0:
        raise ValueError("Среднее арифметическое равно нулю, расчёт коэффициента вариации невозможен")

    std = np.std(arr, ddof=0)  # популяционное стандартное отклонение
    cv = (std / mean) * 100.0

    return {"coefficient_of_variation": cv}

def run(inputs: dict) -> dict:
    import numpy as np

    metrics = inputs.get("CalculatedMetric", [])
    if not metrics:
        raise ValueError("Нет входных данных CalculatedMetric")

    values = []
    unit = None
    for m in metrics:
        df = m.get("derived_fact")
        if df is None:
            continue
        v = df.get("value")
        u = df.get("unit")
        if v is None or u is None:
            continue
        if unit is None:
            unit = u
        elif unit != u:
            raise ValueError(f"Несовместимые единицы измерения: {unit} и {u}")
        values.append(v)

    if len(values) < 2:
        raise ValueError("Недостаточно значений для расчёта коэффициента вариации (нужно минимум 2)")

    arr = np.array(values, dtype=np.float64)
    mean = np.mean(arr)
    if mean == 0:
        raise ValueError("Среднее арифметическое равно нулю, коэффициент вариации не определён")
    std = np.std(arr, ddof=0)  # популяционное стандартное отклонение
    cv = (std / mean) * 100.0

    return {"coefficient_of_variation": cv}
